import numpy as np
A=np.load('source_pixels.npz')['rgb'].astype(int)
for t in range(1,96):
 d=np.max(abs(A[t]-A[t-1]),2)
 for th in [5,15,30,60]:
  ys,xs=np.where(d>th)
  if th==15:
   if len(xs): b=(xs.min(),ys.min(),xs.max(),ys.max())
   else:b=None
   print(f'{t:02d} n15={len(xs):4d} box={b} max={d.max():3d} sum={d.sum():7d}',end=' ')
 print()
PY"
